vector_indexes:
CREATE VECTOR INDEX change_request_embeddings IF NOT EXISTS
    FOR (c:ChangeRequest) ON (c.embedding)
    OPTIONS {indexConfig: {
        `vector.dimensions`: 768,
        `vector.similarity_function`: 'cosine'
    }}

